describe('Share Filtered Search URL', () => {
  const baseUrl = Cypress.config().baseUrl || 'http://localhost:3000';
  const testSearchQuery = 'cypress automation';
  const testFilters = {
    category: 'testing',
    dateRange: 'last-30-days',
    sortBy: 'relevance'
  };

  beforeEach(() => {
    cy.visit(`${baseUrl}/search`);
    cy.clearLocalStorage();
    cy.clearCookies();
  });

  it('should generate and copy shareable filtered search URL', () => {
    // Perform search
    cy.get('[data-testid="search-input"]').type(testSearchQuery);
    cy.get('[data-testid="search-button"]').click();

    // Apply filters
    cy.get('[data-testid="filter-category"]').select(testFilters.category);
    cy.get('[data-testid="filter-date-range"]').select(testFilters.dateRange);
    cy.get('[data-testid="filter-sort"]').select(testFilters.sortBy);

    // Wait for results to update
    cy.get('[data-testid="search-results"]').should('be.visible');

    // Click share button
    cy.get('[data-testid="share-button"]').click();

    // Verify share modal appears
    cy.get('[data-testid="share-modal"]').should('be.visible');

    // Verify URL is generated with all filters
    cy.get('[data-testid="share-url-input"]').should('have.value', (url) => {
      expect(url).to.include(testSearchQuery);
      expect(url).to.include(testFilters.category);
      expect(url).to.include(testFilters.dateRange);
      expect(url).to.include(testFilters.sortBy);
    });

    // Copy URL to clipboard
    cy.get('[data-testid="copy-url-button"]').click();

    // Verify success message
    cy.get('[data-testid="copy-success-message"]').should('be.visible');
    cy.get('[data-testid="copy-success-message"]').should('contain', 'Copied to clipboard');
  });

  it('should load search results when accessing shared filtered URL', () => {
    // Construct filtered search URL
    const filteredUrl = `${baseUrl}/search?q=${encodeURIComponent(testSearchQuery)}&category=${testFilters.category}&dateRange=${testFilters.dateRange}&sortBy=${testFilters.sortBy}`;

    // Visit the shared URL
    cy.visit(filteredUrl);

    // Verify search input contains the query
    cy.get('[data-testid="search-input"]').should('have.value', testSearchQuery);

    // Verify all filters are applied
    cy.get('[data-testid="filter-category"]').should('have.value', testFilters.category);
    cy.get('[data-testid="filter-date-range"]').should('have.value', testFilters.dateRange);
    cy.get('[data-testid="filter-sort"]').should('have.value', testFilters.sortBy);

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);

    // Verify results match the applied filters
    cy.get('[data-testid="search-result-item"]').first().within(() => {
      cy.get('[data-testid="result-category"]').should('contain', testFilters.category);
    });
  });

  it('should handle special characters in search query when sharing', () => {
    const specialCharQuery = 'test & filter | search <tag>';
    const encodedQuery = encodeURIComponent(specialCharQuery);

    cy.get('[data-testid="search-input"]').type(specialCharQuery);
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="search-results"]').should('be.visible');

    cy.get('[data-testid="share-button"]').click();
    cy.get('[data-testid="share-modal"]').should('be.visible');

    // Verify URL properly encodes special characters
    cy.get('[data-testid="share-url-input"]').should('have.value', (url) => {
      expect(url).to.include(encodedQuery);
    });

    cy.get('[data-testid="copy-url-button"]').click();
    cy.get('[data-testid="copy-success-message"]').should('be.visible');
  });

  it('should preserve filters when modifying shared URL parameters', () => {
    const filteredUrl = `${baseUrl}/search?q=${encodeURIComponent(testSearchQuery)}&category=${testFilters.category}`;

    cy.visit(filteredUrl);

    // Verify initial filters are applied
    cy.get('[data-testid="filter-category"]').should('have.value', testFilters.category);

    // Add additional filter
    cy.get('[data-testid="filter-date-range"]').select(testFilters.dateRange);

    // Verify URL updates with new filter
    cy.url().should('include', testFilters.dateRange);

    // Click share button
    cy.get('[data-testid="share-button"]').click();

    // Verify updated URL contains all filters
    cy.get('[data-testid="share-url-input"]').should('have.value', (url) => {
      expect(url).to.include(testSearchQuery);
      expect(url).to.include(testFilters.category);
      expect(url).to.include(testFilters.dateRange);
    });
  });

  it('should handle empty search with filters in shared URL', () => {
    const emptySearchUrl = `${baseUrl}/search?category=${testFilters.category}&dateRange=${testFilters.dateRange}`;

    cy.visit(emptySearchUrl);

    // Verify filters are applied even without search query
    cy.get('[data-testid="filter-category"]').should('have.value', testFilters.category);
    cy.get('[data-testid="filter-date-range"]').should('have.value', testFilters.dateRange);

    // Verify search input is empty
    cy.get('[data-testid="search-input"]').should('have.value', '');

    // Verify results are filtered by applied filters only
    cy.get('[data-testid="search-results"]').should('be.visible');
  });
});
